"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisPricingContent } from "./components/pricing/content";
import View5 from "./components/pricing/variants/08-ledger";
const views={"ledger":View5};
export type { ArtemisPricingBenefits, ArtemisPricingBilling, ArtemisPricingCalculator, ArtemisPricingContent, ArtemisPricingImage, ArtemisPricingLink, ArtemisPricingPlan, ArtemisPricingTier } from "./components/pricing/content";
export interface ArtemisPricingProps {className?:string;variant?:"ledger";/** The words on the pricing section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisPricingContent>;}
export function ArtemisPricing({className,variant="ledger",content}:ArtemisPricingProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisPricingLink {
  label: string;
  href: string;
}

/** A picture shown as content. */
export interface ArtemisPricingImage {
  src: string;
  alt: string;
}

/** The two options of the billing switch. */
export interface ArtemisPricingBilling {
  /** The monthly option. */
  monthly: string;
  /** The yearly option. */
  yearly: string;
  /** What paying yearly saves, such as "Save 20%". command-deck and ledger add it to the yearly option, plans-grid shows it beside it. ledger's estimate takes 20% off whatever this says. */
  saving?: string;
}

/** A usage level of a plan, with its own price. */
export interface ArtemisPricingTier {
  /** The tier's option in the plan's switch, such as "5x". */
  label: string;
  /** Replaces the plan's `price` while the tier is chosen. */
  price?: number;
  /** Replaces the plan's `yearlyPrice` while the tier is chosen. */
  yearlyPrice?: number;
  /** Replaces the plan's `description` while the tier is chosen. */
  description?: string;
  /** Replaces the plan's `cta` while the tier is chosen. */
  cta?: ArtemisPricingLink;
}

/** A plan and its price. */
export interface ArtemisPricingPlan {
  /** A short id such as "pro". shared-benefits uses it as the plan picker's value, or the name when left out. */
  id?: string;
  /** All layouts. */
  name: string;
  /** Who the plan is for. All layouts but aurora-flow. */
  description?: string;
  /** The price per month, or the one-off price, as a number of `currency`. All layouts; ledger adds seats to it. */
  price?: number;
  /** The price per month when billed yearly. ai, shared-benefits, command-deck and plans-grid show it while yearly is chosen, and keep `price` without it. */
  yearlyPrice?: number;
  /** Words shown instead of the price, such as "Free" or "Custom pricing". All layouts. */
  priceLabel?: string;
  /** An earlier price, struck through beside the price. plans-grid. */
  compareAtPrice?: number;
  /** After the price, such as "/ month" or "one time". All layouts. */
  period?: string;
  /** A short line about the price, such as "Billed monthly": under the price in ai, shared-benefits and command-deck, at the foot of the card in plans-grid. With `yearlyNote`, it shows only while monthly is chosen. */
  note?: string;
  /** The line in place of `note` while yearly is chosen, such as "{total} billed yearly"; "{total}" becomes the yearly total with its currency. ai, shared-benefits, command-deck and plans-grid. */
  yearlyNote?: string;
  /** A small tag beside the name, such as "Best value". aurora-flow, visual-plans and plans-grid. */
  badge?: string;
  /** Marks the plan to recommend. ai, visual-plans, command-deck and plans-grid draw it apart; shared-benefits and ledger open on it; aurora-flow shows it. */
  featured?: boolean;
  /** A small heading over the features. ai and visual-plans. */
  featuresTitle?: string;
  /** What the plan includes. All layouts; shared-benefits lists them on one line. */
  features: string[];
  /** The plan's button. All layouts; shared-benefits and ledger show the chosen plan's. "{billing}" in the href becomes the chosen period, "monthly" or "annual" ("yearly" in shared-benefits; always "monthly" in layouts without a switch). */
  cta: ArtemisPricingLink;
  /** Usage levels with their own price, shown as a switch on the plan. ai. */
  tiers?: ArtemisPricingTier[];
  /** Seats the price includes. ledger. */
  includedSeats?: number;
  /** The monthly price of each seat after `includedSeats`. ledger. */
  seatPrice?: number;
}

/** What every plan includes. */
export interface ArtemisPricingBenefits {
  /** A small line over the title. */
  badge?: string;
  title: string;
  items: string[];
}

/** The words on ledger's seat calculator and estimate. The maths stays in the layout. */
export interface ArtemisPricingCalculator {
  /** Before each plan's price in the plan picker, such as "From". */
  from: string;
  /** Before the chosen plan's name, over its details, such as "Selected". */
  selected: string;
  /** After the chosen plan's price, such as "/ base". */
  base: string;
  /** Over the seat count, such as "Team size". */
  teamSize: string;
  /** After the seat count, such as "seats". */
  seats: string;
  /** After the seats a plan includes, such as "included". */
  included: string;
  /** After the price of each extra seat, such as "thereafter". */
  thereafter: string;
  /** Before the chosen plan's name, over the estimate, such as "Estimate". */
  estimate: string;
  /** A tag under the estimate's title, such as "Updates live". */
  live: string;
  /** The estimate's line for the plan's price, such as "Base plan". */
  basePlan: string;
  /** After the number of included seats, such as "included seats". */
  includedSeats: string;
  /** After the number of extra seats, such as "additional seats". */
  extraSeats: string;
  /** The estimate's line for the yearly discount, such as "Annual discount". */
  discount: string;
  /** Over the total, such as "Due monthly". */
  total: string;
  /** After the total, such as "USD". */
  currencyCode: string;
}

/** The words on an Artemis pricing section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisPricingContent {
  /** A short line over the headline. ai, aurora-flow, visual-plans, command-deck, ledger and plans-grid. */
  badge?: string;
  /** All layouts. */
  headline: string;
  /** A sentence or two under the headline. All layouts but ledger. */
  subhead?: string;
  /** The sign before every price, such as "$". All layouts. */
  currency: string;
  /** The billing switch. ai, shared-benefits, command-deck, ledger and plans-grid. */
  billing?: ArtemisPricingBilling;
  /** All layouts. aurora-flow shows the featured plan, or the first; visual-plans looks best with two, the others with three. */
  plans: ArtemisPricingPlan[];
  /** A heading over the plan picker. shared-benefits. */
  plansTitle?: string;
  /** What every plan includes, beside the plan picker. shared-benefits. */
  benefits?: ArtemisPricingBenefits;
  /** The picture over the benefits. shared-benefits. */
  image?: ArtemisPricingImage;
  /** A line of small print: under the plans in ai and plans-grid, under the subhead in aurora-flow, under the button in ledger. */
  footnote?: string;
  /** The words on the seat calculator. ledger. */
  calculator?: ArtemisPricingCalculator;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS, ARTEMIS_SPRING_LAYOUT } from "../../../lib/ease";
import { RangeSlider } from "./08-ledger/range-slider";
import { NumberTicker } from "./08-ledger/number-ticker";
import type { ArtemisPricingContent, ArtemisPricingPlan } from "../content";
const DEFAULT = {
    badge: "Pricing ledger",
    headline: "A price you can explain line by line.",
    currency: "$",
    billing: { monthly: "monthly", yearly: "annual", saving: "\u221220%" },
    plans: [
        { name: "Core", price: 24, period: "/mo", includedSeats: 5, seatPrice: 6, description: "For focused teams shipping their first production workflows.", features: ["Unlimited projects", "50k monthly events", "Community support"], cta: { label: "Start with Core", href: "#" } },
        { name: "Scale", price: 64, period: "/mo", includedSeats: 10, seatPrice: 5, description: "For growing teams that need observability and control.", features: ["500k monthly events", "Audit history", "Priority support"], cta: { label: "Start with Scale", href: "#" }, featured: true },
        { name: "Enterprise", price: 180, period: "/mo", includedSeats: 25, seatPrice: 4, description: "For organizations with security and procurement requirements.", features: ["Unlimited events", "SAML and SCIM", "Dedicated success manager"], cta: { label: "Start with Enterprise", href: "#" } },
    ],
    calculator: {
        from: "From",
        selected: "Selected",
        base: "/ base",
        teamSize: "Team size",
        seats: "seats",
        included: "included",
        thereafter: "thereafter",
        estimate: "Estimate",
        live: "Updates live",
        basePlan: "Base plan",
        includedSeats: "included seats",
        extraSeats: "additional seats",
        discount: "Annual discount",
        total: "Due monthly",
        currencyCode: "USD",
    },
    footnote: "No setup fee / change seats anytime",
} satisfies ArtemisPricingContent;
export default function PricingLedger({ content }: { content?: Partial<ArtemisPricingContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const plans: ArtemisPricingPlan[] = copy.plans;
    const words = copy.calculator ?? DEFAULT.calculator;
    const [annual, setAnnual] = useState(true);
    const [selected, setSelected] = useState(() => Math.max(0, plans.findIndex(option => option.featured)));
    const [seats, setSeats] = useState(12);
    const reduced = useReducedMotion();
    const billingId = useId();
    const planId = useId();
    const plan = plans[selected] ?? plans[0];
    const base = plan.price ?? 0;
    const included = plan.includedSeats ?? 0;
    const extraSeats = Math.max(0, seats - included);
    const extraCost = Math.round(extraSeats * (plan.seatPrice ?? 0) * 100) / 100;
    const total = Math.round((base + extraCost) * (annual ? 0.8 : 1));
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl art:border art:border-border/60 art:bg-background">
            <header className="art:grid art:gap-6 art:border-border/60 art:border-b art:p-6 art:@min-[640px]/artemis:p-8 art:@min-[1024px]/artemis:grid-cols-[1fr_auto] art:@min-[1024px]/artemis:items-end">
              <div>
                {copy.badge && <p className="art:font-mono art:text-xs art:text-primary art:uppercase art:tracking-[0.17em]">
                  {copy.badge}
                </p>}
                <h2 className="art:mt-5 art:max-w-2xl art:text-balance art:text-4xl art:font-medium art:text-foreground art:leading-[1.02] art:tracking-[-0.04em]">
                  {copy.headline}
                </h2>
              </div>
              {copy.billing && <fieldset className="art:flex art:border art:border-border/70">
                <legend className="art:sr-only">
                  {"Billing period"}
                </legend>
                <motion.button whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setAnnual(false)} type="button" className={`art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:hover:bg-transparent art:relative art:h-10 art:min-w-24 art:px-4 art:font-mono art:text-xs art:uppercase art:tracking-[0.12em] art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-foreground art:rounded-full ${!annual ? "art:hover:text-inherit art:text-primary-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} aria-pressed={!annual} tabIndex={0}>
                  {!annual && <motion.span layoutId={billingId} className="art:absolute art:inset-0 art:bg-primary" transition={ARTEMIS_SPRING_LAYOUT}/>}
                  <span className="art:relative">
                    {copy.billing.monthly}
                    {" "}
                  </span>
                </motion.button>
                <motion.button whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setAnnual(true)} type="button" className={`art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:hover:bg-transparent art:relative art:h-10 art:min-w-24 art:px-4 art:font-mono art:text-xs art:uppercase art:tracking-[0.12em] art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-foreground art:rounded-full ${annual ? "art:hover:text-inherit art:text-primary-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} aria-pressed={annual} tabIndex={0}>
                  {annual && <motion.span layoutId={billingId} className="art:absolute art:inset-0 art:bg-primary" transition={ARTEMIS_SPRING_LAYOUT}/>}
                  <span className="art:relative">
                    {copy.billing.yearly}
                    {copy.billing.saving ? ` \u00B7 ${copy.billing.saving}` : " "}
                  </span>
                </motion.button>
              </fieldset>}
            </header>
            <div className="art:grid art:@min-[1024px]/artemis:grid-cols-[1.15fr_0.85fr]">
              <div className="art:border-border/60 art:border-b art:@min-[1024px]/artemis:border-r art:@min-[1024px]/artemis:border-b-0">
                <div className="art:grid art:border-border/60 art:border-b art:@min-[640px]/artemis:grid-cols-3">
                  {plans.map((option, index) => <motion.button key={index} whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setSelected(index)} type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:min-h-24 art:border-border/60 art:border-b art:p-4 art:text-left art:outline-none art:last:border-b-0 art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-foreground art:@min-[640px]/artemis:border-r art:@min-[640px]/artemis:border-b-0 art:@min-[640px]/artemis:last:border-r-0 art:rounded-full" aria-pressed={selected === index} tabIndex={0}>
                    {selected === index && <motion.span layoutId={planId} className="art:absolute art:inset-0 art:bg-primary/[0.07]" transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>}
                    <span className="art:relative art:flex art:items-start art:justify-between art:gap-3">
                      <span>
                        <span className={`art:block art:font-medium ${selected === index ? "art:text-foreground" : "art:text-muted-foreground"}`}>
                          {option.name}
                        </span>
                        <span className="art:mt-2 art:block art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.08em]">
                          {option.priceLabel ?? `${words.from} ${copy.currency}${option.price ?? 0}${option.period ?? ""}`}
                        </span>
                      </span>
                      <span className={`art:mt-1 art:size-2 art:border ${selected === index ? "art:border-primary art:bg-primary" : "art:border-border-strong"}`}/>
                    </span>
                  </motion.button>)}
                </div>
                <AnimatePresence mode="wait" initial={false}>
                <motion.div key={selected} className="art:p-6 art:@min-[640px]/artemis:p-8" initial={reduced ? false : { opacity: 0, x: 18 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: reduced ? 0 : -18 }} transition={{ duration: reduced ? 0 : 0.35, ease: ARTEMIS_EASE_OUT }}>
                  <div className="art:flex art:flex-col art:justify-between art:gap-5 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-start">
                    <div>
                      <p className="art:font-mono art:text-xs art:text-primary art:uppercase art:tracking-[0.14em]">
                        {`${words.selected} / ${plan.name}`}
                      </p>
                      {plan.description && <h3 className="art:mt-3 art:max-w-lg art:text-xl art:font-medium art:text-foreground art:tracking-tight">
                        {plan.description}
                      </h3>}
                    </div>
                    <p className="art:shrink-0 art:font-mono art:text-3xl art:text-foreground art:tabular-nums art:tracking-[-0.05em]">
                      {plan.priceLabel ?? <>
                      {`${copy.currency}${base}`}
                      <span className="art:text-muted-foreground art:text-xs art:tracking-normal">
                        {" "}
                        {words.base}
                      </span>
                      </>}
                    </p>
                  </div>
                  <div className="art:mt-9 art:border-border/60 art:border-y art:py-6">
                    <div className="art:flex art:items-end art:justify-between art:gap-4">
                      <div>
                        <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em]">
                          {words.teamSize}
                        </p>
                        <p className="art:mt-2 art:font-mono art:text-4xl art:text-foreground art:tabular-nums art:tracking-[-0.06em]">
                          {seats}
                          <span className="art:ml-2 art:text-muted-foreground art:text-xs art:tracking-normal">
                            {words.seats}
                          </span>
                        </p>
                      </div>
                      <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.09em]">
                        {`${included} ${words.included}`}
                        <br />
                        {`${copy.currency}${plan.seatPrice ?? 0} ${words.thereafter}`}
                      </p>
                    </div>
                    <RangeSlider min={1} max={50} step={1} value={seats} onValueChange={setSeats} aria-label="Team seats" showTicks={false} className="art:mt-6 art:rounded-lg art:bg-foreground/[0.06] art:[&>div:first-child]:bg-primary/20 art:[&_[role=slider]]:rounded-lg art:[&_[role=slider]]:bg-primary"/>
                  </div>
                  <ul className="art:mt-7 art:grid art:gap-3 art:@min-[640px]/artemis:grid-cols-3">
                    {plan.features.map((feature, index) => <motion.li key={index} className="art:flex art:items-start art:gap-2 art:border-border/60 art:border-t art:pt-3 art:text-foreground art:text-sm art:leading-5" initial={reduced ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.35, delay: reduced ? 0 : index * 0.06, ease: ARTEMIS_EASE_OUT }}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:mt-0.5 art:size-3.5 art:shrink-0 art:text-primary" aria-hidden="true">
                        <path d="M20 6 9 17l-5-5"/>
                      </svg>
                      {feature}
                    </motion.li>)}
                  </ul>
                </motion.div>
                </AnimatePresence>
              </div>
              <aside className="art:relative art:overflow-hidden art:p-6 art:@min-[640px]/artemis:p-8">
                <div className="art:pointer-events-none art:absolute art:inset-0 art:[background-image:linear-gradient(to_right,color-mix(in_oklch,var(--artemis-foreground)_4%,transparent)_1px,transparent_1px),linear-gradient(to_bottom,color-mix(in_oklch,var(--artemis-foreground)_4%,transparent)_1px,transparent_1px)] art:[background-size:32px_32px]"/>
                <div className="art:relative art:border art:border-border/70 art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
                  <div className="art:flex art:items-center art:justify-between art:gap-4 art:border-border/60 art:border-b art:pb-4">
                    <div>
                      <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.13em]">
                        {`${words.estimate} / ${plan.name}`}
                      </p>
                      <p className="art:mt-1 art:font-mono art:text-xs art:text-primary art:uppercase art:tracking-[0.1em]">
                        {words.live}
                      </p>
                    </div>
                    <span className="art:grid art:size-8 art:place-items-center art:bg-primary art:text-primary-foreground art:rounded-full">
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                        <path d="M5 12h14"/>
                        <path d="m12 5 7 7-7 7"/>
                      </svg>
                    </span>
                  </div>
                  <div className="art:space-y-4 art:py-6 art:font-mono art:text-xs">
                    <div className="art:flex art:items-center art:justify-between art:gap-4">
                      <span className="art:flex art:items-center art:gap-2 art:text-muted-foreground">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-3" aria-hidden="true">
                          <path d="M5 12h14"/>
                        </svg>
                        {words.basePlan}
                      </span>
                      <span className="art:text-foreground">
                        {plan.priceLabel ?? `${copy.currency}${base}`}
                      </span>
                    </div>
                    <div className="art:flex art:items-center art:justify-between art:gap-4">
                      <span className="art:flex art:items-center art:gap-2 art:text-muted-foreground">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-3" aria-hidden="true">
                          <path d="M5 12h14"/>
                        </svg>
                        {`${included} ${words.includedSeats}`}
                      </span>
                      <span className="art:text-foreground">
                        {`${copy.currency}0`}
                      </span>
                    </div>
                    <div className="art:flex art:items-center art:justify-between art:gap-4">
                      <span className="art:flex art:items-center art:gap-2 art:text-muted-foreground">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-3" aria-hidden="true">
                          <path d="M5 12h14"/>
                        </svg>
                        {`${extraSeats} ${words.extraSeats}`}
                      </span>
                      <span className="art:text-foreground">
                        {`${copy.currency}${extraCost}`}
                      </span>
                    </div>
                    <div className="art:flex art:items-center art:justify-between art:gap-4">
                      <span className="art:flex art:items-center art:gap-2 art:text-muted-foreground">
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-3" aria-hidden="true">
                          <path d="M5 12h14"/>
                        </svg>
                        {words.discount}
                      </span>
                      <span className={annual ? "art:text-primary" : "art:text-foreground"}>
                        {annual ? "\u221220%" : "\u2014"}
                      </span>
                    </div>
                  </div>
                  <div className="art:flex art:items-end art:justify-between art:gap-4 art:border-border/70 art:border-t art:pt-5">
                    <div>
                      <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em]">
                        {words.total}
                      </p>
                      <p className="art:mt-2 art:font-mono art:font-semibold art:text-5xl art:text-foreground art:tabular-nums art:tracking-[-0.07em]">
                        <NumberTicker value={total} prefix={copy.currency} startOnView={false}/>
